107|  nextStep: () => void;
108|  prevStep: () => void;
109|  setSelectedProvider: (provider: string) => void;
110|  setApiKey: (key: string) => void;
111|  toggleShowApiKey: () => void;
112|  setConnectionStatus: (status: 'idle' | 'testing' | 'success' | 'error') => void;
113|  setConnectionError: (error: string | null) => void;
114|  completeOnboarding: () => void;
115|  reset: () => void;
