128|export const useOnboardingStore = create<OnboardingState>()(
129|  persist(
130|    (set, get) => ({
131|      ...initialState,
132|
133|      setStep: (step) => set({ step }),
134|      nextStep: () => set((state) => ({ step: Math.min(state.step + 1, 5) })),
135|      prevStep: () => set((state) => ({ step: Math.max(state.step - 1, 0) })),
136|      setSelectedProvider: (provider) => set({ selectedProvider: provider }),
137|      setApiKey: (key) => set({ apiKey: key }),
138|      toggleShowApiKey: () => set((state) => ({ showApiKey: !state.showApiKey })),
